              "type": "string",
              "direction": "input",
              "binding": "vars.setVendorContext1.output.vendorName"
            },
            {
              "id": "creditscore",
              "label": "Credit Score",
              "type": "number",
              "direction": "input",
              "binding": "vars.setVendorContext1.output.creditScore"
            },
            {
              "id": "approved",
              "label": "Approved",
              "type": "boolean",
              "direction": "output",
              "variable": "vars.approved",
              "required": true
            },
            {
              "id": "risk_notes",
