          "type": "string",
          "description": "Task completion status",
          "source": "=result.Action",
          "var": "status",
          "enum": ["Approve", "Reject"],
          "default": "Approve"
        }
      }
    },
    {
      "id": "approvalDecision1",
      "type": "core.logic.decision",
      "typeVersion": "1.1",
      "display": {
        "label": "Approved?"
      },
      "inputs": {
        "expression": "$vars.complianceReview1.output.approved",
        "trueLabel": "Approved",
        "falseLabel": "Rejected"
      }
    },
    {
      "id": "vendorOnboarded1",
      "type": "core.action.script",
      "typeVersion": "1.0",
      "display": {
        "label": "Vendor Onboarded"
      },
      "inputs": {
        "script": "return { message: \"Vendor onboarded\", vendorName: $vars.setVendorContext1.output.vendorName };"
